package com.nexodb.tools;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;

public final class SqlProjectServiceTest {
    public static void main(String[] args)throws Exception{
        Path parent=Files.createTempDirectory("adisdb-sql-project-");SqlProjectService project=SqlProjectService.create(parent.resolve("ventas"),"Ventas");equal("Ventas",project.name());Path folder=project.createFolder(Path.of("reportes"));equal(Path.of("reportes"),folder);Path file=project.createSql(Path.of("reportes","mensual"));equal(Path.of("reportes","mensual.sql"),file);project.write(file,"SELECT 1;\n");equal("SELECT 1;\n",project.read(file).text());reject(()->project.write(Path.of("..","escape.sql"),"SELECT 1"));
        require(project.gitAvailable(),"Git is required for SQL project integration");ok(project.initGit());ok(project.configureIdentity("AdisDB Test","adisdb@example.invalid"));ok(project.stageAll());ok(project.commit("proyecto inicial"));equal(Map.of(),project.gitStatuses());
        project.write(file,"SELECT 2;\n");equal("M",project.gitStatuses().get("reportes/mensual.sql"));require(project.diff(file).contains("SELECT 2"),"Working-tree diff missing");require(project.history(file).contains("proyecto inicial"),"File history missing");ok(project.stage(file));require(project.gitSummary().output().contains("mensual.sql"),"Staged status missing");ok(project.commit("segunda consulta"));Path remote=parent.resolve("remote.git");command(parent,"git","init","--bare",remote.toString());ok(project.configureRemote(remote.toString(),"main"));equal(remote.toString(),project.remoteUrl());ok(project.push());require(command(parent,"git","--git-dir",remote.toString(),"show-ref","--verify","refs/heads/main").contains("refs/heads/main"),"Remote main branch missing");reject(()->project.configureRemote(remote.toString(),"../unsafe"));
        command(project.root(),"git","checkout","-b","feature/reportes");Files.writeString(project.root().resolve("feature.sql"),"SELECT 'feature';\n");command(project.root(),"git","add","feature.sql");command(project.root(),"git","commit","-m","rama de reportes");command(project.root(),"git","checkout","main");Files.writeString(project.root().resolve("principal.sql"),"SELECT 'main';\n");command(project.root(),"git","add","principal.sql");command(project.root(),"git","commit","-m","cambio principal");command(project.root(),"git","merge","--no-ff","feature/reportes","-m","fusion visual");List<SqlProjectService.GitGraphLine> graph=project.historyGraph(null);require(graph.stream().anyMatch(line->line.commit()!=null&&line.commit().parents().size()>1&&line.commit().subject().contains("fusion visual")),"Merge commit missing from visual graph");require(graph.stream().anyMatch(line->line.graph().contains("/")||line.graph().contains("\\")),"Branch connection missing from visual graph");String mergeHash=graph.stream().filter(line->line.commit()!=null&&line.commit().subject().contains("fusion visual")).findFirst().orElseThrow().commit().hash();require(project.commitDetails(mergeHash).contains("fusion visual"),"Commit details missing");ok(project.runConsole("git status --short --branch"));reject(()->project.runConsole("git clean -fd"));
        Path renamed=project.rename(file,"ventas_mes");equal(Path.of("reportes","ventas_mes.sql"),renamed);require(project.entries().stream().anyMatch(entry->entry.relative().equals(renamed)),"Renamed SQL missing");project.delete(renamed);equal(false,Files.exists(project.root().resolve(renamed)));project.delete(Path.of("reportes"));
        System.out.println("SqlProjectServiceTest: OK (safe SQL projects, GitHub lifecycle and colored branch/merge graph data)");
    }
    private static void ok(SqlProjectService.GitResult result){if(!result.ok())throw new AssertionError(result.output());}
    private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
    private static void reject(Throwing work)throws Exception{try{work.run();throw new AssertionError("Unsafe path accepted");}catch(IOException expected){}}
    private static void equal(Object expected,Object actual){if(!Objects.equals(expected,actual))throw new AssertionError("Expected ["+expected+"] got ["+actual+"]");}
    private static String command(Path directory,String...command)throws Exception{Process process=new ProcessBuilder(command).directory(directory.toFile()).redirectErrorStream(true).start();String output=new String(process.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);if(process.waitFor()!=0)throw new AssertionError(output);return output;}
    @FunctionalInterface private interface Throwing{void run()throws Exception;}
}
